changeSet.sql:
ALTER TABLE zc_outreach_request
  ADD CONSTRAINT fk_zc_outreach_request_tenant FOREIGN KEY (tenant_id) REFERENCES zc_tenant (id);
ALTER TABLE zc_outreach_request
  ADD CONSTRAINT fk_zc_outreach_request_member FOREIGN KEY (tenant_id, member_id)
    REFERENCES zc_member_reference (tenant_id, id);
ALTER TABLE zc_outreach_request
  ADD CONSTRAINT fk_zc_outreach_request_enrolment FOREIGN KEY (tenant_id, enrolment_id, member_id)
    REFERENCES zc_enrolment (tenant_id, id, member_id);

ALTER TABLE zc_outreach_delivery
  ADD CONSTRAINT fk_zc_outreach_delivery_tenant FOREIGN KEY (tenant_id) REFERENCES zc_tenant (id);
ALTER TABLE zc_outreach_delivery
  ADD CONSTRAINT fk_zc_outreach_delivery_outreach_request FOREIGN KEY (tenant_id, outreach_request_id)
    REFERENCES zc_outreach_request (tenant_id, id);

ALTER TABLE zc_inbound_message
  ADD CONSTRAINT fk_zc_inbound_message_tenant FOREIGN KEY (tenant_id) REFERENCES zc_tenant (id);
ALTER TABLE zc_inbound_message
  ADD CONSTRAINT fk_zc_inbound_message_member FOREIGN KEY (tenant_id, member_id)
    REFERENCES zc_member_reference (tenant_id, id);

-- Tenant isolation. The app must connect as zc_app: superusers bypass RLS.
ALTER TABLE zc_outreach_request ENABLE ROW LEVEL SECURITY;
ALTER TABLE zc_outreach_request FORCE ROW LEVEL SECURITY;
CREATE POLICY rls_zc_outreach_request_tenant ON zc_outreach_request
  USING (tenant_id = zc_current_tenant())
  WITH CHECK (tenant_id = zc_current_tenant());
ALTER TABLE zc_outreach_delivery ENABLE ROW LEVEL SECURITY;
ALTER TABLE zc_outreach_delivery FORCE ROW LEVEL SECURITY;
CREATE POLICY rls_zc_outreach_delivery_tenant ON zc_outreach_delivery
  USING (tenant_id = zc_current_tenant())
  WITH CHECK (tenant_id = zc_current_tenant());
ALTER TABLE zc_inbound_message ENABLE ROW LEVEL SECURITY;
ALTER TABLE zc_inbound_message FORCE ROW LEVEL SECURITY;
CREATE POLICY rls_zc_inbound_message_tenant ON zc_inbound_message
  USING (tenant_id = zc_current_tenant())
  WITH CHECK (tenant_id = zc_current_tenant());

rollback.sql:
DROP POLICY rls_zc_outreach_request_tenant ON zc_outreach_request;
ALTER TABLE zc_outreach_request NO FORCE ROW LEVEL SECURITY;
ALTER TABLE zc_outreach_request DISABLE ROW LEVEL SECURITY;
DROP POLICY rls_zc_outreach_delivery_tenant ON zc_outreach_delivery;
ALTER TABLE zc_outreach_delivery NO FORCE ROW LEVEL SECURITY;
ALTER TABLE zc_outreach_delivery DISABLE ROW LEVEL SECURITY;
DROP POLICY rls_zc_inbound_message_tenant ON zc_inbound_message;
ALTER TABLE zc_inbound_message NO FORCE ROW LEVEL SECURITY;
ALTER TABLE zc_inbound_message DISABLE ROW LEVEL SECURITY;

changeSet.sql:
GRANT SELECT, INSERT, UPDATE ON zc_outreach_request TO zc_app;
GRANT USAGE ON SEQUENCE zc_outreach_request_id_seq TO zc_app;
GRANT SELECT, INSERT, UPDATE ON zc_outreach_delivery TO zc_app;
GRANT USAGE ON SEQUENCE zc_outreach_delivery_id_seq TO zc_app;
GRANT SELECT, INSERT, UPDATE ON zc_inbound_message TO zc_app;
GRANT USAGE ON SEQUENCE zc_inbound_message_id_seq TO zc_app;

rollback.sql:
REVOKE ALL ON zc_outreach_request FROM zc_app;
REVOKE USAGE ON SEQUENCE zc_outreach_request_id_seq FROM zc_app;
REVOKE ALL ON zc_outreach_delivery FROM zc_app;
REVOKE USAGE ON SEQUENCE zc_outreach_delivery_id_seq FROM zc_app;
REVOKE ALL ON zc_inbound_message FROM zc_app;
REVOKE USAGE ON SEQUENCE zc_inbound_message_id_seq FROM zc_app;
